#include "mesh.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <sys/wait.h>
#include <sys/file.h>
#include <fcntl.h>
#include <unistd.h>
namespace fs=std::filesystem;
Json read(const fs::path&p){std::ifstream f(p);if(!f)throw std::runtime_error(p.string());Json j;f>>j;return j;}
void save(const fs::path&p,const Json&j){fs::create_directories(p.parent_path());std::ofstream(p)<<j.dump(2)<<'\n';}
void run(const fs::path&exe,const std::vector<std::string>&args,const fs::path&log){pid_t pid=fork();if(pid==0){int fd=open(log.c_str(),O_CREAT|O_WRONLY|O_TRUNC,0644);dup2(fd,1);dup2(fd,2);close(fd);std::vector<char*>v;std::string bin=exe.string();v.push_back(bin.data());for(auto&a:args)v.push_back(const_cast<char*>(a.c_str()));v.push_back(nullptr);execv(bin.c_str(),v.data());_exit(127);}if(pid<0)throw std::runtime_error("fork");int s;waitpid(pid,&s,0);if(!WIFEXITED(s)||WEXITSTATUS(s))throw std::runtime_error("child failed: "+log.string());}
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("run INPUTS BIN GRAPHS OUTPUT");fs::path inputs=fs::absolute(argv[1]),bin=fs::absolute(argv[2]),graphs=fs::absolute(argv[3]),out=fs::absolute(argv[4]);if(fs::exists(out/"SUMMARY.json"))throw std::runtime_error("Refusing overwrite");fs::create_directories(out);int lock=open((out/"coordinator.lock").c_str(),O_CREAT|O_RDWR|O_CLOEXEC,0644);if(lock<0||flock(lock,LOCK_EX|LOCK_NB))throw std::runtime_error("Already running");auto protocol=read(inputs/"PROTOCOL.json");Json rows=Json::array();for(const auto&lv:protocol.at("levels")){std::string level=lv;auto scene_path=inputs/"assets"/level/"scene.json";auto scene=read(scene_path);auto folder=out/level;fs::create_directories(folder);save(out/"STATUS.json",{{"state","running"},{"level",level},{"completed",rows.size()},{"pid",getpid()}});auto before=std::chrono::steady_clock::now();run(bin/"wang_planner",{(graphs/(level+"_wang2023")).string(),folder.string(),"solve"},folder/"process.log");double wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-before).count();auto result=read(folder/"result.json");Json assessment=nullptr;std::string verdict=result.at("failure")=="no_converged_local_candidate"?"未找到":"未完成";if(!result.at("durations").empty()){assessment=mesh_evaluate(Trajectory::load(result),scene);save(folder/"assessment.json",assessment);if(assessment.at("collision_detected").get<bool>())verdict="碰撞";else if(result.at("found").get<bool>())verdict=assessment.at("passed").get<bool>()?"通过":(!assessment.at("ordered_exactly_once").get<bool>()||!assessment.at("endpoints_passed").get<bool>())?"未完成":"证据不足";}double max_ms=0;int calls=0,success=0;for(auto&q:result["requests"]){max_ms=std::max(max_ms,q["cycle_ms"].get<double>());for(auto&c:q["candidates"]){++calls;if(c["stats"]["eligible"].get<bool>())++success;}}rows.push_back({{"level",level},{"verdict",verdict},{"found",result["found"]},{"trajectory_s",result["found"].get<bool>()?result.at("nominal_time_s"):Json(nullptr)},{"executed_prefix_s",result["nominal_time_s"]},{"compute_s",wall},{"solve_s",result["solve_s"]},{"max_local_cycle_ms",max_ms},{"candidates",calls},{"converged_candidates",success},{"failure",result["failure"]},{"result",(folder/"result.json").string()}});save(out/"SUMMARY.json",rows);std::ofstream report(out/"PLANNING.md");report<<"# Wang 独立复现：22条件规划\n\n仅理想参考轨迹拼接，无Gazebo。原N2/M4、中心等式、三次正部积分软罚，局部终点与四时间初值是复现适配。通过是共同实体几何、门序与终点数值检查通过。完整时间必须到原任务终点；中止项仅列前缀，不算竞速成绩。已执行前缀碰撞优先显示碰撞，并保留中止原因。\n\n|条件|结论|完整轨迹/s|已生成前缀/s|计算墙钟/s|最长局部请求/ms|中止原因|\n|---|---|---:|---:|---:|---:|---|\n";report<<std::fixed<<std::setprecision(3);for(auto&r:rows){report<<"|"<<r["level"].get<std::string>()<<"|"<<r["verdict"].get<std::string>()<<"|";if(r["trajectory_s"].is_null())report<<"—";else report<<r["trajectory_s"].get<double>();report<<"|"<<r["executed_prefix_s"].get<double>()<<"|"<<r["compute_s"].get<double>()<<"|"<<r["max_local_cycle_ms"].get<double>()<<"|"<<(r["failure"].is_null()?"—":r["failure"].get<std::string>())<<"|\n";}std::cout<<level<<" "<<verdict<<" "<<rows.back()["trajectory_s"]<<" "<<wall<<std::endl;}save(out/"STATUS.json",{{"state","complete"},{"completed",rows.size()},{"pid",getpid()}});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
